// Automatic chlorine dosing PID-like control
var residual = ReadDouble("WaterPlant.Disinfection.ChlorineResidual_mgl");
var setpoint = 0.8;
var error = setpoint - residual;
var currentDose = ReadDouble("WaterPlant.Disinfection.ChlorineDose_mgl");
var newDose = currentDose + error * 0.1;
newDose = Math.Max(0.5, Math.Min(2.0, newDose));
Write("WaterPlant.Disinfection.ChlorineDose_mgl", Math.Round(newDose, 2));
